import csv
import io
import re


_NUMBER = re.compile(
    r"^[+-]?(?:(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?|inf(?:inity)?|nan)$",
    re.IGNORECASE,
)


def parse_csv(raw_csv: str):
    try:
        records = [
            row
            for row in csv.reader(
                io.StringIO(raw_csv, newline=""),
                delimiter=",",
                quotechar='"',
                strict=False,
            )
            if row and any(value.strip() for value in row)
        ]
    except csv.Error:
        records = []

    if not records:
        return {"columns": ["column_1", "column_2"], "rows": []}

    def is_numeric_row(row):
        return len(row) == 2 and all(_NUMBER.fullmatch(value.strip()) for value in row)

    first_data = next(
        (index for index, row in enumerate(records) if is_numeric_row(row)),
        next((index for index, row in enumerate(records) if len(row) == 2), 0),
    )

    header = None
    if first_data > 0:
        candidate = records[first_data - 1]
        if len(candidate) == 2 and not is_numeric_row(candidate):
            header = candidate

    columns = header[:] if header is not None else ["column_1", "column_2"]
    rows = []

    for record in records[first_data:]:
        if len(record) < 2:
            normalized = record[:] + [""] * (2 - len(record))
        elif len(record) > 2:
            normalized = [record[0], ",".join(record[1:])]
        else:
            normalized = record[:]
        rows.append(normalized)

    return {"columns": columns, "rows": rows}
